const input = $input.first().json;
const raw = input.body || input;

const get = (key) => raw[key] || raw?.properties?.[key]?.value || raw?.properties?.[key] || '';

const firstName         = get('firstName') || get('firstname');
const lastName          = get('lastName') || get('lastname');
const email             = get('email');
const website           = get('website');
const message           = get('message');
const decisionMaker     = get('decisionMaker') || get('decision_maker');
const annualRevenue     = get('annualRevenue') || get('annual_revenue');
const numberOfEmployees = parseInt(get('numberOfEmployees') || get('numberofemployees')) || 0;
const contactId         = raw.id || raw.contactId || input.id || '';

let score = 0;
const breakdown = [];

// REVENUE (25pts) — Starter sweet spot is under $1M
const revenueScores = {
  'Under $100K': 25,
  '$100K - $500K': 25,
  '$500K - $1M': 20,
  '$1M - $5M': 10,   // edge case — may belong in growth
  'Prefer not to say': 10
};
const revPts = revenueScores[annualRevenue] || 0;
score += revPts;
breakdown.push(`Revenue (${annualRevenue}): +${revPts}pts`);

// TEAM SIZE (20pts) — Starter is 1-10 people
let sizePts = 0;
if (numberOfEmployees >= 1 && numberOfEmployees <= 10) sizePts = 20;
else if (numberOfEmployees > 10 && numberOfEmployees <= 20) sizePts = 10;
else if (numberOfEmployees === 0) sizePts = 15; // solo, not provided
score += sizePts;
breakdown.push(`Team size (${numberOfEmployees || 'solo'}): +${sizePts}pts`);

// DECISION MAKER (20pts)
const dmPts = decisionMaker === 'Yes' ? 20 : 0;
score += dmPts;
breakdown.push(`Decision maker (${decisionMaker}): +${dmPts}pts`);

// BUSINESS EMAIL (5pts)
const genericDomains = ['gmail.com','yahoo.com','hotmail.com','outlook.com','icloud.com'];
const emailDomain = email.split('@')[1]?.toLowerCase() || '';
const emailPts = !genericDomains.includes(emailDomain) ? 5 : 0;
score += emailPts;
breakdown.push(`Business email: +${emailPts}pts`);

// Bucket (pre-AI — will be recalculated after AI node)
let bucket = 'cold';
if (score >= 45) bucket = 'hot';
else if (score >= 25) bucket = 'warm';

return [{ json: {
  contactId, firstName, lastName, email, website,
  message, decisionMaker, annualRevenue, numberOfEmployees,
  tier: 'starter',
  hardScore: score,
  preBucket: bucket,
  breakdown: breakdown.join(' | ')
}}];

const prev = $('⚡ Score Starter Lead').first().json;
const aiInput = $input.first().json;

let aiData = { messageScore: 0, likelyWorkflow: 'Not specified', painPoint: 'Not specified' };
try {
  if (aiInput?.messageScore !== undefined) {
    aiData = {
      messageScore: aiInput.messageScore,
      likelyWorkflow: aiInput.likelyWorkflow || 'Not specified',
      painPoint: aiInput.painPoint || 'Not specified'
    };
  }
} catch(e) {}

const totalScore = Math.min(100, prev.hardScore + aiData.messageScore);

let bucket = 'cold';
if (totalScore >= 50) bucket = 'hot';
else if (totalScore >= 30) bucket = 'warm';

return [{ json: {
  ...prev,
  messageScore: aiData.messageScore,
  likelyWorkflow: aiData.likelyWorkflow,
  painPoint: aiData.painPoint,
  totalScore,
  bucket,
  fullBreakdown: prev.breakdown + ` | Message quality: +${aiData.messageScore}pts | TOTAL: ${totalScore}/100 → ${bucket.toUpperCase()}`
}}];
